	public void unAssignInstitution( UnAssignInstitutionFromCompliancePolicyCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignInstitution(command.getCompliancePolicyId());
	}
	




